1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"strings"
8	)
9	
10	// This file holds the shared structural validation for the single-object
11	// JSON registration documents: rule versions (rules.go) and suppression
12	// conditions (alerts.go). Both must contain exactly one JSON object with
13	// nothing but whitespace around it and with no field declared twice in the
14	// same object; the scan runs before the typed decoder reads any business
15	// value, so strings and numbers are never normalized here.
16	//
17	// The two document families keep their own public wording and sentinel
18	// errors, their own idea of which nested objects carry a field table of
19	// their own, and their own way of detecting content after the closing
20	// brace. Those differences are injected through specPolicy; the tokenizing
21	// machinery below exists once.
22	
23	// specPolicy configures scanJSONObject for one registration document
24	// family.
25	type specPolicy struct {
26		// topObject labels the root object in duplicate-field errors.
27		topObject string
28		// known maps the lowercase spelling of every accepted root field to
29		// its canonical name.
30		known map[string]string
31		// nested names the known fields whose value is itself an object that
32		// must carry its own per-object duplicate table. Any other object or
33		// array value is consumed without looking inside.
34		nested map[string]nestedObjectSpec
35		// rejectExactUnknown makes an exact re-spelling of even an unknown key
36		// (same bytes after JSON unescaping) a duplicate. Case-only variants of
37		// unknown keys stay undetected here and surface as unknown fields in
38		// the typed decode.
39		rejectExactUnknown bool
40	
41		// firstTokenError reports a failure to read any first token (including
42		// empty input, which surfaces as io.EOF).
43		firstTokenError func(err error) error
44		// nonObject reports a first token that is not an opening brace.
45		nonObject func(tok json.Token) error
46		// wrap prefixes syntax errors found while scanning the object.
47		wrap func(err error) error
48		// duplicate reports a repeated field. For known fields field is the
49		// canonical name; for an exact unknown-key repeat it is the key itself.
50		// first is the earlier spelling, spelling the current one.
51		duplicate func(obj, field, first, spelling string) error
52		// trailing reports content after the closing brace, given the raw
53		// document and the byte offset just past it.
54		trailing func(raw []byte, offset int) error
55	}
56	
57	// scanJSONObject proves raw holds exactly one JSON object with no repeated
58	// field in any scanned object and with no content after it beyond what the
59	// policy's trailing check allows. It never interprets values.
60	func scanJSONObject(raw []byte, p specPolicy) error {
61		dec := json.NewDecoder(bytes.NewReader(raw))
62		first, err := dec.Token()
63		if err != nil {
64			return p.firstTokenError(err)
65		}
66		if d, ok := first.(json.Delim); !ok || d != '{' {
67			return p.nonObject(first)
68		}
69		if err := scanObject(dec, p, p.known, p.topObject); err != nil {
70			return err
71		}
72		return p.trailing(raw, int(dec.InputOffset()))
73	}
74	
75	// scanObject consumes one object whose opening brace has already been read
76	// and checks its keys against known. obj names the object for duplicate
77	// errors. Objects named in the policy's nested table are scanned with that
78	// table; every other container is skipped without looking inside.
79	func scanObject(dec *json.Decoder, p specPolicy, known map[string]string, obj string) error {
80		seen := make(map[string]string, len(known))
81		spellings := make(map[string]string)
82		for dec.More() {
83			keyTok, err := dec.Token()
84			if err != nil {
85				return p.wrap(err)
86			}
87			key, ok := keyTok.(string)
88			if !ok {
89				return p.wrap(fmt.Errorf("object key is %s, want string", jsonTokenName(keyTok)))
90			}
91			target, knownKey := known[strings.ToLower(key)]
92			if p.rejectExactUnknown {
93				// An exact repeat of a decoded key name (known or unknown) is a
94				// duplicate; escapes are decoded first, so "id" == "id".
95				if first, dup := spellings[key]; dup {
96					return p.duplicate(obj, key, first, key)
97				}
98				spellings[key] = key
99			}
100			if knownKey {
101				// A case-only spelling of the same known field is the same
102				// field: "Severity" and "severity" cannot share one object.
103				if first, dup := seen[target]; dup {
104					return p.duplicate(obj, target, first, key)
105				}
106				seen[target] = key
107			}
